import json

from marshmallow import Schema, fields
from marshmallow.schema import CONTEXT


def test_dumps_forwards_context():
    class ContextField(fields.Integer):
        def _serialize(self, value, attr, obj, **kwargs):
            value *= (CONTEXT.get() or {}).get("factor", 1)
            return super()._serialize(value, attr, obj, **kwargs)

    class ContextSchema(Schema):
        ctx_fld = ContextField()

    schema = ContextSchema()
    assert schema.dump({"ctx_fld": 1}, context={"factor": 2}) == {"ctx_fld": 2}
    result = schema.dumps({"ctx_fld": 1}, context={"factor": 2})
    assert json.loads(result) == {"ctx_fld": 2}

