from marshmallow import CONTEXT, Schema, fields, ValidationError


class ContextField(fields.Integer):
    def _deserialize(self, value, attr, data, **kwargs):
        val = super()._deserialize(value, attr, data, **kwargs)
        ctx = CONTEXT.get() or {}
        if ctx.get("factor") != 2:
            raise ValidationError("context missing")
        return val * ctx["factor"]


class ContextSchema(Schema):
    ctx_fld = ContextField()


def test_validate_honours_context_like_load():
    schema = ContextSchema()
    # load with context works on HEAD
    assert schema.load({"ctx_fld": 1}, context={"factor": 2}) == {"ctx_fld": 2}
    # validate should behave consistently with load given the same context
    errors = schema.validate({"ctx_fld": 1}, context={"factor": 2})
    assert errors == {}
